export type Provider = 'anthropic' | 'cerebras' | 'deepinfra' | 'deepseek' | 'google' | 'groq' | 'mistral' | 'openai' | 'openrouter' | 'perplexity' | 'togetherai' | 'vercel' | 'xai' | (string & {});
export interface AnthropicThinkingConfig {
    budgetTokens?: number;
}
export interface OpenAIThinkingConfig {
    reasoningEffort?: 'low' | 'medium' | 'high';
}
export interface GoogleThinkingConfig {
    thinkingBudget?: number;
    thinkingLevel?: 'minimal' | 'low' | 'medium' | 'high';
}
export interface XaiThinkingConfig {
    reasoningEffort?: 'low' | 'high';
}
export type ThinkingConfigFor<P> = P extends 'anthropic' ? AnthropicThinkingConfig : P extends 'google' ? GoogleThinkingConfig : P extends 'xai' ? XaiThinkingConfig : P extends string ? OpenAIThinkingConfig : ThinkingConfig;
export type ThinkingConfig = AnthropicThinkingConfig | OpenAIThinkingConfig | GoogleThinkingConfig | XaiThinkingConfig;
